-- Resources content for the content library's search and pagination.
-- Content only; see 20260928200000_resources_release_helpers.sql.

select private.rc_release_guide(
  p_slug => 'log-content-library',
  p_tool_key => 'log',
  p_title => 'Building the content library',
  p_summary => 'Find, add, and approve news, promos, and other spots, or import WUWF''s existing DAD cut library in bulk.',
  p_screen_keys => array['log.library'],
  p_sort_order => 10,
  p_version_note => 'Added searching and paging the library.',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The content library holds everything a rundown can pull from — news, promos, membership messages, PSAs, legal IDs, and more. Any tool member can add to it, not just producers."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Find an item"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Type in the search box to search titles, DAD cart numbers, and scripts. The list updates as you type; pressing Enter searches straight away."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Clear the box to see the whole library again."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use the status chips (All, Approved, Draft, Retired) and the content type chips to narrow the list. Each status chip shows how many items it would show."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The library shows 25 items a page, newest first. The page links under the table move between pages."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Add a content item"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the library, select "},{"type":"text","text":"+ New content item","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fill in a title, content type, summary, script, expected duration, and effective dates."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Create content item","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Add its components"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the item's page, expand "},{"type":"text","text":"Add a component","marks":[{"type":"bold"}]},{"type":"text","text":" — choose a type (live intro, recorded audio, live outro, or an optional tag), a sequence, a duration, and a script. Select "},{"type":"text","text":"Add component","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A required component counts toward the item's total time; an optional one doesn't."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Approve it"}]},{"type":"paragraph","content":[{"type":"text","text":"An item starts as a draft. Set its status to Approved, in the Status panel on its page, before it can be picked for a rundown — only approved items are offered when filling a break."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Import WUWF's DAD cut library"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"From the library, open the import screen and upload the Standard Library export from DAD (Library screen → Generate Reports → Standard Library) — optionally with its companion Groups report."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Preview import","marks":[{"type":"bold"}]},{"type":"text","text":" to see the plan: new items, updates to existing ones, and anything it couldn't place."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Import","marks":[{"type":"bold"}]},{"type":"text","text":" to confirm."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"There's no audio upload here. WUWF's playback system (ENCO/DAD) is where recorded material actually plays from — a content item is metadata and a script, not an audio file."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Re-running the import later updates an already-imported item in place (matched by its DAD cart number) instead of creating a duplicate."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Retiring stale content is an ordinary status change, not a delete — nothing in the library is ever removed outright."}]}]}]}]}$body$);

select private.rc_release_note(
  p_slug => 'release-2026-09-29-log-library-search',
  p_tool_key => 'log',
  p_released_on => '2026-09-29',
  p_title => 'Search the content library, a page at a time',
  p_guide_slugs => array['log-content-library'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The content library has a search box that looks through titles, DAD cart numbers, and scripts, and it now shows 25 items a page with page links underneath. Status and content type are chips instead of drop-downs, and each status chip shows its count. Search boxes on list screens across the portal now search as you type, and clearing one shows the full list again without pressing Enter."}]}]}$body$
);
